import {mountCustomBuildingLibrary} from './custom-building-library-ui.js?v=architecture-collection-57';
import {DIRECTIONAL_BUILDINGS,directionalBuildingSprite,loadDirectionalBuilding} from './directional-buildings.js?v=architecture-collection-57';
import {parseBuildingSlot,sameBuildingFootprint} from './building-footprints.js?v=architecture-collection-57';
import {isBuildingLotRoot} from './building-lots.js?v=architecture-collection-57';
import {buildingDesignCanvas,defaultLotDesign,importBuildingDesign,applyBuildingDesign} from './building-designs.js?v=architecture-collection-57';
import {buildingStyleKey,REPLACEABLE_STYLES,replaceBuildingStyle,canReplaceBuilding} from './building-art.js?v=architecture-collection-57';
export {canReplaceBuilding} from './building-art.js?v=architecture-collection-57';
function preview(renderer,index,footprint={width:1,height:1},rotation=renderer.rotation){const s=DIRECTIONAL_BUILDINGS[index]?directionalBuildingSprite(renderer,index,footprint,rotation):renderer.sprites[index];if(!s)return DIRECTIONAL_BUILDINGS[index]?buildingDesignCanvas(defaultLotDesign(index,footprint),rotation).toDataURL('image/png'):'';const canvas=document.createElement('canvas');canvas.width=180;canvas.height=200;const ctx=canvas.getContext('2d'),scale=Math.min(160/s.w,180/s.h);ctx.drawImage(s.atlas,s.x,s.y,s.w,s.h,(180-s.w*scale)/2,190-s.h*scale,s.w*scale,s.h*scale);return canvas.toDataURL('image/png');}
export function showBuildingReplacement({city,renderer,dialog,apply,back,draftMode=false},tile){
 const key=typeof tile==='string'?tile:buildingStyleKey(city,tile),{source,footprint}=parseBuildingSlot(key),current=city.buildingReplacements?.[key]??source,style=REPLACEABLE_STYLES[source],count=city.tiles.filter(t=>canReplaceBuilding(t)&&isBuildingLotRoot(city,t)&&buildingStyleKey(city,t)===key).length;let pointerHeld=false,keyHeld=false,imported=false,request=0,draft=city.buildingDesigns?.[key];let rotation=renderer.rotation,showCustom=Boolean(city.buildingDesigns?.[key]);const artwork=index=>DIRECTIONAL_BUILDINGS[index]?preview(renderer,index,footprint,rotation):footprint.width===1&&footprint.height===1?preview(renderer,index,footprint,rotation):buildingDesignCanvas(defaultLotDesign(index,footprint),rotation).toDataURL('image/png');
 dialog('Replace building style',`<p>${draftMode?'These changes stay in the building manager’s draft until you apply the building set. ':''}Replace every instance of <strong>${style.name}</strong> with a ${footprint.width} × ${footprint.height} tile footprint in this city: ${count} current building${count===1?'':'s'}. Future buildings of this style and footprint use the replacement too. Population, jobs, costs and zoning stay the same.</p><div class="replacement-previews"><div><h3>Original style</h3><img id="replacementOriginal" src="${artwork(source)}" alt="${style.name}"></div><div><h3 id="replacementPreviewTitle">Selected replacement</h3><img id="replacementPreview" src="${city.buildingDesigns?.[key]?buildingDesignCanvas(city.buildingDesigns[key],rotation).toDataURL('image/png'):artwork(current)}" alt="${city.buildingDesigns?.[key]?'Custom building model':REPLACEABLE_STYLES[current].name}"></div></div><div class="actions"><button id="replacementCompare" aria-pressed="false" title="Hold with the pointer, Space or Enter to compare">Hold to view original</button><button id="replacementRotateBack" aria-label="Rotate preview counterclockwise">Rotate left</button><span id="replacementDirection" role="status"></span><button id="replacementRotate" aria-label="Rotate preview clockwise">Rotate right</button></div><p id="replacementViewNote" class="fine"></p><label>Building style<select id="replacementStyle">${Object.entries(REPLACEABLE_STYLES).filter(([,v])=>v.group===style.group).map(([key,v])=>`<option value="${key}" ${Number(key)===current?'selected':''}>${v.name}</option>`).join('')}</select></label><div class="actions"><label>Import custom building<input id="replacementFile" type="file" accept=".json,application/json"></label></div><p id="replacementImportStatus" role="status"></p><div id="replacementCustomLibrary"></div><div class="actions"><button id="applyReplacement" class="primary">Apply to every instance</button><button id="revertReplacement" ${current===source&&!city.buildingDesigns?.[key]?'disabled':''}>Revert original style</button><button id="cancelReplacement">Cancel</button></div><p class="fine">The replacement library covers ${Object.keys(REPLACEABLE_STYLES).length} residential, commercial and non-farm industrial styles. Replacements stay within the same zone family, but may have a different visual height. Farms keep their connected barn and field artwork. Import a matching SIMS3000 building file here, or use City desk → Building designer to create one. Imported models remain drafts until applied. The full replacement catalog remains unfinished.</p>`);
 const applyLabel=draftMode?'Use in draft set':'Apply to every instance';
 const select=document.querySelector('#replacementStyle');
 const updatePreview=(load=true)=>{
  if(document.querySelector('#replacementStyle')!==select)return;
  const value=Number(select.value),image=document.querySelector('#replacementPreview'),custom=showCustom&&draft,rotatable=Boolean(custom||DIRECTIONAL_BUILDINGS[value]||footprint.width>1||footprint.height>1);
  document.querySelector('#applyReplacement').disabled=Boolean(custom&&!imported);document.querySelector('#applyReplacement').textContent=custom&&!imported?'Custom model applied':applyLabel;
  document.querySelector('#revertReplacement').disabled=!custom&&value===source;
  image.src=custom?buildingDesignCanvas(custom,rotation).toDataURL('image/png'):artwork(value);image.alt=custom?'Custom building model':REPLACEABLE_STYLES[value].name;
  const original=artwork(source);document.querySelector('#replacementOriginal').src=original;
  const comparing=pointerHeld||keyHeld;document.querySelector('#replacementCompare').setAttribute('aria-pressed',String(comparing));document.querySelector('#replacementPreviewTitle').textContent=comparing?'Original style · comparing':'Selected replacement';
  if(comparing){image.src=original;image.alt=style.name;}
  document.querySelector('#replacementDirection').textContent=rotatable?['North','East','South','West'][rotation]:'Fixed view';
  document.querySelector('#replacementRotate').disabled=!rotatable;document.querySelector('#replacementRotateBack').disabled=!rotatable;
  document.querySelector('#replacementViewNote').textContent=rotatable?(footprint.width===1&&footprint.height===1&&!DIRECTIONAL_BUILDINGS[source]?'The original artwork has one fixed view. The selected model rotates independently of your city camera.':'Preview rotation does not change your city camera.'):'This artwork currently has one fixed view.';
  if(load&&!custom&&DIRECTIONAL_BUILDINGS[value])loadDirectionalBuilding(value,footprint).then(()=>{if(document.querySelector('#replacementStyle')===select&&Number(select.value)===value&&document.querySelector('#replacementPreview')===image&&!showCustom)updatePreview(false);},()=>{});
 };
 const compare=document.querySelector('#replacementCompare');
 compare.onpointerdown=event=>{if(event.button!==0)return;pointerHeld=true;compare.setPointerCapture?.(event.pointerId);updatePreview(false);};
 compare.onpointerup=compare.onpointercancel=compare.onlostpointercapture=()=>{pointerHeld=false;updatePreview(false);};
 compare.onkeydown=event=>{if(event.key===' '||event.key==='Enter'){event.preventDefault();keyHeld=true;updatePreview(false);}else if(event.key==='Escape'){pointerHeld=keyHeld=false;updatePreview(false);}};
 compare.onkeyup=event=>{if(event.key===' '||event.key==='Enter'){event.preventDefault();keyHeld=false;updatePreview(false);}};
 compare.onblur=()=>{pointerHeld=keyHeld=false;updatePreview(false);};
 const fileInput=document.querySelector('#replacementFile'),status=document.querySelector('#replacementImportStatus');
 fileInput.onchange=async()=>{const file=fileInput.files?.[0],id=++request;if(!file)return;status.textContent='Reading custom building…';try{
  if(file.size>32768)throw Error('Building files must be smaller than 32 KB.');
  const model=importBuildingDesign(await file.text());if(id!==request||document.querySelector('#replacementStyle')!==select)return;
  if(!sameBuildingFootprint(model.footprint,footprint))throw Error(`Choose a building with a ${footprint.width} × ${footprint.height} tile footprint.`);
  draft=model;imported=showCustom=true;pointerHeld=keyHeld=false;updatePreview();status.textContent=`${model.name} imported as a draft. Apply to every instance when ready.`;
 }catch(error){if(id===request&&document.querySelector('#replacementStyle')===select)status.textContent=error.message||'Could not read the building file.';}finally{if(id===request)fileInput.value='';}};
 select.onchange=()=>{request++;pointerHeld=keyHeld=false;showCustom=imported=false;status.textContent='';updatePreview();};
 document.querySelector('#replacementRotate').onclick=()=>{rotation=(rotation+1)%4;updatePreview();};
 document.querySelector('#replacementRotateBack').onclick=()=>{rotation=(rotation+3)%4;updatePreview();};
 updatePreview();
 mountCustomBuildingLibrary({host:document.querySelector('#replacementCustomLibrary'),footprint,getDraft:()=>showCustom?draft:null,selectDesign:model=>{request++;draft=model;imported=showCustom=true;pointerHeld=keyHeld=false;updatePreview();status.textContent=`${model.name} selected from your saved list. Apply when ready.`;}});
 const commit=target=>{request++;replaceBuildingStyle(city,key,target);apply();back();};document.querySelector('#applyReplacement').onclick=()=>{request++;if(showCustom&&imported){applyBuildingDesign(city,key,draft);apply();back();}else if(!showCustom)commit(Number(select.value));};document.querySelector('#revertReplacement').onclick=()=>{request++;pointerHeld=keyHeld=false;showCustom=imported=false;select.value=String(source);updatePreview();status.textContent='Original artwork selected. Apply to every instance to restore it, or Cancel to keep your current artwork.';};document.querySelector('#cancelReplacement').onclick=()=>{request++;back();};
}
